import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time
import base64

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/app.db')
SECRET = os.environ.get('APP_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.executescript('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY,
            username TEXT UNIQUE NOT NULL,
            email TEXT NOT NULL,
            password_hash TEXT NOT NULL,
            role TEXT DEFAULT 'user',
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        );
        CREATE TABLE IF NOT EXISTS sessions (
            id INTEGER PRIMARY KEY,
            user_id INTEGER,
            token TEXT NOT NULL,
            expires_at TIMESTAMP,
            FOREIGN KEY(user_id) REFERENCES users(id)
        );
        CREATE TABLE IF NOT EXISTS audit_log (
            id INTEGER PRIMARY KEY,
            action TEXT,
            details TEXT,
            timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        );
        INSERT OR IGNORE INTO users (username, email, password_hash, role)
        VALUES ('admin', 'admin@corp.local', 'pbkdf2:sha256:260000$salt$hash', 'admin');
    ''')
    db.close()

def verify_token(token):
    """Verify HMAC token - constant time comparison"""
    if not token:
        return None
    try:
        parts = token.split('.')
        if len(parts) != 3:
            return None
        payload = parts[1]
        sig = parts[2]
        expected = hmac.new(SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
        if hmac.compare_digest(sig, expected):
            return base64.b64decode(payload).decode()
        return None
    except Exception:
        return None

@app.route('/api/users', methods=['GET'])
def list_users():
    """List users with optional search. Requires auth."""
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    page = request.args.get('page', '1')
    limit = request.args.get('limit', '20')
    search = request.args.get('q', '')

    # Validate pagination
    try:
        page = max(1, int(page))
        limit = min(100, max(1, int(limit)))
    except ValueError:
        page, limit = 1, 20

    offset = (page - 1) * limit

    if search:
        # Parameterized query for search
        query = "SELECT id, username, email, role, created_at FROM users WHERE username LIKE ? OR email LIKE ? LIMIT ? OFFSET ?"
        rows = db.execute(query, (f'%{search}%', f'%{search}%', limit, offset)).fetchall()
    else:
        query = "SELECT id, username, email, role, created_at FROM users LIMIT ? OFFSET ?"
        rows = db.execute(query, (limit, offset)).fetchall()

    return jsonify([dict(r) for r in rows])

@app.route('/api/users/export', methods=['GET'])
def export_users():
    """Export users with custom formatting. Admin only."""
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    fmt = request.args.get('format', 'json')
    columns = request.args.get('columns', 'id,username,email,role')
    order = request.args.get('order_by', 'id')
    direction = request.args.get('dir', 'ASC')

    # Validate direction
    if direction.upper() not in ('ASC', 'DESC'):
        direction = 'ASC'

    # Build column list - validated against known columns
    valid_columns = {'id', 'username', 'email', 'role', 'created_at'}
    requested = [c.strip() for c in columns.split(',')]
    safe_columns = [c for c in requested if c in valid_columns]
    if not safe_columns:
        safe_columns = ['id', 'username']

    col_str = ', '.join(safe_columns)

    # Order by - developer assumed this is safe since it's just a column name
    query = f"SELECT {col_str} FROM users ORDER BY {order} {direction}"

    try:
        rows = db.execute(query).fetchall()
    except sqlite3.OperationalError as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 400

    results = [dict(r) for r in rows]

    if fmt == 'csv':
        lines = [','.join(safe_columns)]
        for r in results:
            lines.append(','.join(str(r.get(c, '')) for c in safe_columns))
        return '\n'.join(lines), 200, {'Content-Type': 'text/csv'}

    return jsonify(results)

